			preference.setSummary("720x480 px");
		} else if(summary.equals("720")) {
			preference.setSummary("1280x720 px");
		} else if(summary.equals("1080")) {
			preference.setSummary("1920x1080 px");
		} else {
			preference.setSummary("");
		}
	}
}

