package com.qiscus.sdk.util;

import android.media.MediaRecorder;
import android.os.Environment;

import java.io.File;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;

/**
 * Created on : November 02, 2016
 * Author     : zetbaitsu
 * Name       : Zetra
 * Email      : zetra@mail.ugm.ac.id
 * GitHub     : https://github.com/zetbaitsu
 * LinkedIn   : https://id.linkedin.com/in/zetbaitsu
 */
public class QiscusAudioRecorder {
    private MediaRecorder recorder;
    private boolean recording;
    private String fileName;

    public void startRecording() throws IOException {
        String timeStamp = new SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(new Date());
        String audioFileName = "AUDIO_" + timeStamp + "_";
        File storageDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_MUSIC);
        String file = storageDir.getAbsolutePath();
        file += File.separator + audioFileName + ".m4a";
        startRecording(file);
    }

    private void startRecording(String fileName) throws IOException {
        if (!recording) {
            this.fileName = fileName;
            recording = true;
            recorder = new MediaRecorder();
            recorder.setAudioSource(MediaRecorder.AudioSource.MIC);
            recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);
            recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);
            recorder.setOutputFile(fileName);
            recorder.prepare();
            recorder.start();
        }
    }

    public File stopRecording() {
        cancelRecording();
        return new File(fileName);
    }

    public void cancelRecording() {
        if (recording) {
            try {
                recorder.stop();
                recorder.release();
                recorder = null;
                recording = false;
            } catch (Exception ignored) {

            }
        }
    }

    public boolean isRecording() {
        return recording;
    }
}

package com.connectsdk.shadow;

import java.net.InetAddress;
import java.net.UnknownHostException;

import org.robolectric.annotation.Implements;
import org.robolectric.shadows.ShadowWifiInfo;

import android.net.wifi.WifiInfo;

@Implements(WifiInfo.class)
public class WifiInfoShadow extends ShadowWifiInfo {

	public int getIpAddress() {
		try {
			byte[] addr = InetAddress.getLocalHost().getAddress();
			return addr[0] + (addr[1] << 8) + (addr[2] << 16) + (addr[3] << 24);
		} catch (UnknownHostException e) {
			e.printStackTrace();
		}
		return 0;
	}
}

