package com.facebook.imagepipeline.producers;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.concurrent.Executor;

import android.net.Uri;
import android.util.Base64;

import com.facebook.common.internal.Preconditions;
import com.facebook.common.internal.VisibleForTesting;
import com.facebook.imagepipeline.memory.PooledByteBufferFactory;
import com.facebook.imagepipeline.request.ImageRequest;

/**
 * Producer for data URIs.
 *
 * <p>Data URIs embed the data in the URI itself. They don't point to a file location;
 * the URI is the data. Data can be encoded in either base-64 or escaped ASCII.
 * See the <a href="http://tools.ietf.org/html/rfc2397">spec</a> for full details.
 *
 * <p>Data URIs are intended for small pieces of data only, since the URI lives on the Java
 * heap. For large data, use a another URI type.
 *
 * <p>Charsets specified in the URI are ignored. Only UTF-8 encoding is currently supported.
 */
public class DataFetchProducer extends LocalFetchProducer {

  private static final String PRODUCER_NAME = "DataFetchProducer";

  public DataFetchProducer(
      Executor executor,
      PooledByteBufferFactory pooledByteBufferFactory) {
    super(executor, pooledByteBufferFactory);
  }

  @Override
  protected InputStream getInputStream(ImageRequest imageRequest) throws IOException {
    return new ByteArrayInputStream(getData(imageRequest.getSourceUri().toString()));
  }

  @Override
  protected int getLength(ImageRequest imageRequest) {
    return getData(imageRequest.getSourceUri().toString()).length;
  }

  @Override
  protected String getProducerName() {
    return PRODUCER_NAME;
  }

  @VisibleForTesting
  static byte[] getData(String uri) {
    /*
     * Format of a data URL:
     * data:mime/type;param=value;param=value;base64,actual_data
     * everything is optional except the actual data, which is either
     * base-64 or escaped ASCII encoded.
     */
    Preconditions.checkArgument(uri.substring(0, 5).equals("data:"));
    int commaPos = uri.indexOf(',');

    String dataStr = uri.substring(commaPos + 1, uri.length());
    if (isBase64(uri.substring(0, commaPos))) {
      return Base64.decode(dataStr, Base64.DEFAULT);
    } else {
      String str = Uri.decode(dataStr);
      byte[] b = str.getBytes();
      return b;
    }
  }

  @VisibleForTesting
  static boolean isBase64(String prefix) {
    if (!prefix.contains(";")) {
      return false;
    }
    String[] parameters = prefix.split(";");
    return parameters[parameters.length - 1].equals("base64");
  }
}

package com.spiddekauga.android.ui;

import android.support.annotation.StringRes;
import android.text.SpannableString;
import android.text.Spanned;
import android.text.style.ClickableSpan;

import com.spiddekauga.android.AppActivity;
import com.spiddekauga.android.BuildConfig;
import com.spiddekauga.utils.Strings;

/**
 * Creates a clickable SpannableString from a resource. Automatically determines where the clickable
 * part from the resource. The resource should contain the clickable part between ||clickable text||
 * i.e. between the pipes.
 */
public class SpanStringHelper {
private static final String DELIMITER = "\\|\\|";

/**
 * Creates a clickable SpannableString from a resource. Automatically determines where the clickable
 * part from the resource. The resource should contain the clickable part between ||clickable text||
 * i.e. between the pipes.
 * @param stringId the string to create the spannable text from
 * @param clickableListeners array of all clickable spans listeners, should match the number of
 * clickable lists
 */
public static SpannableString createSpannableString(@StringRes int stringId, ClickableSpan... clickableListeners) {
	String text = AppActivity.getActivity().getResources().getString(stringId);
	String[] spans = text.split(DELIMITER, -1);

	// Check so listeners matches the spans
	// It should be clickableListener * 2 + 1
	if (BuildConfig.DEBUG) {
		if (spans.length != (clickableListeners.length * 2) + 1) {
			throw new IllegalArgumentException("Text \"" + text + "\" does not contain " + clickableListeners.length + " clickable parts");
		}
	}

	String displayText = Strings.merge(spans);
	SpannableString spannableString = new SpannableString(displayText);

	// Bind each clickable state
	int totalLength = 0;
	for (int i = 0; i < spans.length - 1; i += 2) {
		int beginIndex = totalLength + spans[i].length();
		int length = spans[i + 1].length();
		int endIndex = beginIndex + length;

		spannableString.setSpan(clickableListeners[i / 2], beginIndex, endIndex, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);

		totalLength = endIndex;
	}

	return spannableString;
}
}

