            return column.isUnique()? typeName + " UNIQUE ON CONFLICT IGNORE" : typeName;
        }
    }

    public static String sqlValue(DbValue value) {
        return value.isText()? "'" + value.toText() + '\'' : Integer.toString(value.toInt());
    }
}

