    true
  } else if (definition.required || value?.text?.isBlank() == true) {
    false
  } else value != null && Patterns.EMAIL_ADDRESS.matcher(value.text).matches()
}

private fun hasValue(value: FieldValue.Text?): Boolean {
  return value?.text?.isNotEmpty() == true
}

