    override fun apply(@NonNull runnable: Runnable): Runnable {
        return Runnable {
            countingIdlingResource.increment()

            try {
                runnable.run()
            } finally {
                countingIdlingResource.decrement()
            }
        }
    }

    val idlingResource: IdlingResource
        get() = countingIdlingResource

}

