     * default but may be disabled in scenarios where Fragments are "recycled" (such as when using
     * a [FragmentStatePagerAdapter].
     */
    open val shouldClearOnDestroy: Boolean = true

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Bridge.restoreInstanceState(this, savedInstanceState)
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        Bridge.saveInstanceState(this, outState)
    }

    override fun onDestroy() {
        super.onDestroy()
        if (shouldClearOnDestroy) Bridge.clear(this)
    }
}

package com.louiscad.splittiessample.extensions.dialog

import android.app.Dialog
import com.louiscad.splittiessample.extensions.coroutines.raceOf
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.launch
import kotlinx.coroutines.selects.select
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlin.coroutines.resume

suspend fun <R> Dialog.showInScope(
    dismissValue: R,
    block: suspend () -> R
): R = try {
    raceOf({
        suspendCancellableCoroutine<R> { c ->
            setOnDismissListener { c.resume(dismissValue) }
            show()
        }
    }, {
        block()
    })
} finally {
    dismiss()
}

suspend fun <R> Dialog.showInScope(
    onDismiss: suspend () -> R,
    block: suspend () -> R
): R = try {
    coroutineScope {
        @UseExperimental(ExperimentalCoroutinesApi::class)
        val dismissJob = launch(start = CoroutineStart.UNDISPATCHED) {
            suspendCancellableCoroutine<Unit> { c ->
                setOnDismissListener { c.resume(Unit) }
                show()
            }
        }
        @UseExperimental(ExperimentalCoroutinesApi::class)
        val blockAsync = async(start = CoroutineStart.UNDISPATCHED) {
            block()
        }
        select<R> {
            blockAsync.onAwait { result ->
                dismissJob.cancel()
                result
            }
            dismissJob.onJoin {
                blockAsync.cancel()
                onDismiss()
            }
        }
    }
} finally {
    dismiss()
}

suspend fun Dialog.showInScope(
    block: suspend () -> Unit
): Unit = try {
    raceOf({
        suspendCancellableCoroutine<Unit> { c ->
            setOnDismissListener { c.resume(Unit) }
            show()
        }
    }, {
        block()
    })
} finally {
    dismiss()
}

